{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.SQCOM_REPLEN_DEC_2025 AS WITH SALES AS ( SELECT CREATED_AT, branch_code, store_name, sku, CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN LEFT(SKU, LENGTH(SKU) - LENGTH(REVERSE(SUBSTRING(REVERSE(SKU), 1, POSITION(\'-\', REVERSE(SKU)) - 1))) - 1) ELSE SKU END AS sku_group, category, REVERSE(SUBSTRING(REVERSE(SKU), 1, POSITION(\'-\', REVERSE(SKU)) - 1)) AS size, SUM(QUANTITY) AS SOLD_QTY, SUM(SUM(QUANTITY)) OVER (PARTITION BY branch_code, CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN LEFT( SKU, LENGTH(SKU) - LENGTH( REVERSE(SUBSTRING(REVERSE(SKU), 1, POSITION(\'-\', REVERSE(SKU)) - 1))) - 1) ELSE SKU END) / 7 AS ROS FROM SNITCH_DB.MAPLEMONK.OMNI_ORDER_PROCESSING_META WHERE (LOCATION LIKE \'%BOHQ%\' OR LOCATION LIKE \'%BOH1Q%\') AND status NOT LIKE \'%CANCELLED%\' AND CAST(CREATED_AT AS DATE) = CURRENT_DATE - 1 GROUP BY 1,2,3,4,5,6,7 ), Inventory AS ( SELECT branch_code, STORE_NAME, sku, CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN LEFT(SKU, LENGTH(SKU) - LENGTH(REVERSE(SUBSTRING(REVERSE(SKU), 1, POSITION(\'-\', REVERSE(SKU)) - 1))) - 1) ELSE SKU END AS sku_group, REVERSE(SUBSTRING(REVERSE(SKU), 1, POSITION(\'-\', REVERSE(SKU)) - 1)) AS size, category_code, SUM(inventory_total) AS inventory FROM snitch_db.maplemonk.omni_inventory_meta WHERE location LIKE \'%BOH1Q%\' OR location like \'%BOHQ%\' GROUP BY 1,2,3,4,5,6 ), priority_defined as ( SELECT CAST(v.store_code AS INT) AS BRANCH_CODE, CAST(v.priority AS INT) AS PRIORITY, ROW_NUMBER() OVER ( ORDER BY CAST(v.priority AS INT) ) AS priority_order FROM ( SELECT 13 AS store_code, 1 AS priority union all SELECT 52 AS store_code, 2 AS priority union all SELECT 73 AS store_code, 3 AS priority ) v ), replen_size_thresholds AS ( SELECT s.branch_code, pd.priority, s.sku, s.sku_group, s.category, s.size, COALESCE(s.sold_qty,0) AS sold_qty, COALESCE(i.inventory, 0) AS inventory, CASE WHEN UPPER(TRIM(s.category)) IN ( \'HOODIES\',\'JACKETS\',\'OVERSHIRT\',\'SHIRTS\',\'SWEATERS\',\'SWEATSHIRTS\',\'T-SHIRTS\') THEN CASE UPPER(TRIM(s.size)) WHEN \'S\' THEN GREATEST(2 - COALESCE(i.inventory,0), 0) WHEN \'M\' THEN GREATEST(4 - COALESCE(i.inventory,0), 0) WHEN \'L\' THEN GREATEST(3 - COALESCE(i.inventory,0), 0) WHEN \'XL\' THEN GREATEST(1 - COALESCE(i.inventory,0), 0) WHEN \'XS\' THEN GREATEST(1 - COALESCE(i.inventory,0), 0) WHEN \'XXL\' THEN GREATEST(1 - COALESCE(i.inventory,0), 0) ELSE 0 END WHEN UPPER(TRIM(s.category)) IN ( \'CARGO PANTS\',\'JEANS\',\'JOGGERS\',\'TRACKPANTS\',\'SHORTS\',\'TROUSERS\') THEN CASE TRIM(s.size) WHEN \'30\' THEN GREATEST(3 - COALESCE(i.inventory,0), 0) WHEN \'32\' THEN GREATEST(4 - COALESCE(i.inventory,0), 0) WHEN \'34\' THEN GREATEST(3 - COALESCE(i.inventory,0), 0) WHEN \'36\' THEN GREATEST(1 - COALESCE(i.inventory,0), 0) WHEN \'28\' THEN GREATEST(1 - COALESCE(i.inventory,0), 0) WHEN \'38\' THEN GREATEST(1 - COALESCE(i.inventory,0), 0) ELSE 0 END ELSE 0 END AS REPLEN_UNITS FROM SALES s LEFT JOIN Inventory i ON s.branch_code=i.branch_code and s.sku_group = i.sku_group AND UPPER(TRIM(s.size)) = UPPER(TRIM(i.size)) left join priority_defined pd on s.branch_code = pd.branch_code ), ranked_stores AS ( SELECT BRANCH_CODE_PRIORITY, short_name AS region FROM SNITCH_DB.MAPLEMONK.GOOGLE_SHEET_FRESH_PRIORITY ), warehouse_stock AS ( SELECT facility, \"Item SkuCode\" as sku, inventory FROM SNITCH_DB.MAPLEMONK.quick_com_live_inv_new WHERE inventory > 1 ), warehouse_preference AS ( SELECT r.SKU, r.branch_code, r.REPLEN_UNITS, rs.region, r.PRIORITY, w.facility, w.inventory, CASE WHEN rs.region = \'North\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 1 WHEN rs.region = \'North\' AND w.facility <> \'SAPL-NORTH-TAURU\' THEN 2 WHEN rs.region = \'South\' AND w.facility <> \'SAPL-NORTH-TAURU\' THEN 1 WHEN rs.region = \'South\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 2 ELSE 3 END AS base_priority FROM replen_size_thresholds r JOIN warehouse_stock w ON r.SKU = w.SKU LEFT JOIN ranked_stores rs ON r.branch_code = rs.BRANCH_CODE_PRIORITY WHERE NOT (rs.region = \'South\' AND w.facility = \'SAPL-NORTH-TAURU\') ), ordered_warehouses AS ( SELECT *, ROW_NUMBER() OVER( PARTITION BY SKU, branch_code ORDER BY base_priority ASC, inventory DESC, facility ) AS warehouse_order FROM warehouse_preference ), allocation_base AS ( SELECT o.SKU, o.branch_code, o.PRIORITY, o.region, o.facility, o.warehouse_order, o.REPLEN_UNITS, o.inventory, o.base_priority, COALESCE( SUM(o.REPLEN_UNITS) OVER( PARTITION BY o.SKU, o.facility ORDER BY o.base_priority ASC, o.PRIORITY ASC, o.branch_code ASC, o.warehouse_order ASC ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ), 0 ) AS cum_req_before_fac, (o.inventory - COALESCE( SUM(o.REPLEN_UNITS) OVER( PARTITION BY o.SKU, o.facility ORDER BY o.base_priority ASC, o.PRIORITY ASC, o.branch_code ASC, o.warehouse_order ASC ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ), 0 ) ) AS remaining_facility_before FROM ordered_warehouses o ), allocation_with_stop AS ( SELECT a.*, GREATEST(LEAST(a.remaining_facility_before, a.REPLEN_UNITS), 0) AS allocatable_here, COALESCE( SUM(GREATEST(LEAST(remaining_facility_before, REPLEN_UNITS), 0)) OVER ( PARTITION BY SKU, branch_code ORDER BY base_priority ASC, inventory DESC, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ), 0 ) AS cum_allocatable_before_store FROM allocation_base a ), final_rpL as ( SELECT SKU, branch_code, region, PRIORITY, facility, warehouse_order, REPLEN_UNITS, inventory, base_priority, LEAST( GREATEST(REPLEN_UNITS - cum_allocatable_before_store, 0), GREATEST(allocatable_here, 0) ) AS allocated_units FROM allocation_with_stop WHERE LEAST( GREATEST(REPLEN_UNITS - cum_allocatable_before_store, 0), GREATEST(allocatable_here, 0) ) > 0 ORDER BY SKU, base_priority, PRIORITY, branch_code, warehouse_order) select * from final_rpl ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.SQCOM_REPLEN_UPLOAD_FORMAT AS WITH replen_output AS ( SELECT branch_code, sku, facility, allocated_units FROM SNITCH_DB.MAPLEMONK.SQCOM_REPLEN_DEC_2025 WHERE allocated_units > 0 QUALIFY ROW_NUMBER() OVER ( PARTITION BY SKU, branch_code, facility ORDER BY allocated_units DESC ) = 1 ), MAX_ORDER_NUM AS ( SELECT MAX(RIGHT(order_name, 5)) AS order_name_max FROM ( SELECT *, TRY_TO_DATE(\"DATE\", \'DD/MM/YYYY\') AS converted_date FROM snitch_db.maplemonk.GS_B2B_UC WHERE \"DATE\" != \'.\' AND TRY_TO_DATE(\"DATE\", \'DD/MM/YYYY\') >= \'2025-11-25\' ) ), STORE_DETAILS_UC AS ( SELECT * FROM SNITCH_DB.MAPLEMONK.GS__SO_IMPORT_MASTER ), COST_PRICE_MAPPING AS ( SELECT sku, MAX(cost_price) AS cost_price FROM SNITCH_DB.MAPLEMONK.UC_FINAL_ITEM_MASTER GROUP BY 1 ), SO_number_prep AS ( SELECT r.*, LPAD( TO_VARCHAR( COALESCE(m.order_name_max, 0) + CASE r.facility WHEN \'SAPL-WH2\' THEN 1 WHEN \'SAPL-WH1\' THEN 2 WHEN \'SAPL-NORTH-TAURU\' THEN 3 ELSE 0 END ), 5, \'0\' ) AS so_number_5d FROM replen_output r CROSS JOIN MAX_ORDER_NUM m ), store_details_join AS ( SELECT p.*, uc.so_code, uc.store_name, CONCAT( \'QC-\', CASE WHEN LOWER(TRIM(uc.so_code)) = \'hrbrla\' THEN \'KALYAN\' ELSE COALESCE(uc.so_code, \'\') END, COALESCE(p.so_number_5d, \'\') ) AS so_code_so_number, CASE WHEN UPPER(TRIM(uc.store_name)) ILIKE \'%FOCO%\' THEN cosp.cost_price * 1.25 ELSE cosp.cost_price END AS cost_price FROM SO_number_prep p LEFT JOIN STORE_DETAILS_UC uc ON p.branch_code = uc.store_code LEFT JOIN COST_PRICE_MAPPING cosp ON LOWER(TRIM(p.SKU)) = LOWER(TRIM(cosp.sku)) ), store_details_join_seq AS ( SELECT sdj.*, ROW_NUMBER() OVER ( PARTITION BY sdj.so_code_so_number ORDER BY sdj.SKU, sdj.branch_code, sdj.facility ) AS item_seq FROM store_details_join sdj ), FINAL_OUTPUT AS ( SELECT sdj.so_code_so_number AS \"Sales Order Code*\", sdj.so_code_so_number AS \"Display Sales Order Code\", uc.EMAIL_ID AS \"Notification Email\", NULL AS \"Notification Mobile\", 1 AS \"COD*\", uc.CHANNEL AS \"Channel\", NULL AS \"Priority\", uc.STORE_CODE AS \"Shipping Address Id\", uc.SHIPPING_ADDRESS_NAME AS \"Shipping Address Name\", uc.SHIPPING_ADDRESS_LINE_2 AS \"Shipping Address Line 1\", uc.COMPANY_NAME AS \"Shipping Address Line 2\", uc.SHIPPING_ADDRESS_CITY AS \"Shipping Address City\", uc.SHIPPING_ADDRESS_STATE AS \"Shipping Address State\", uc.SHIPPING_ADDRESS_COUNTRY AS \"Shipping Address Country\", uc.SHIPPING_ADDRESS_PINCODE AS \"Shipping Address Pincode\", NULL AS \"Shipping Address Latitude\", NULL AS \"Shipping Address Longitude\", uc.SHIPPING_ADDRESS_PHONE AS \"Shipping Address Phone\", uc.BILLING_ADDRESS_ID AS \"Billing Address Id\", uc.BILLING_ADDRESS_NAME AS \"Billing Address Name\", uc.BILLING_ADDRESS_LINE_1 AS \"Billing Address Line 1\", uc.BILLING_ADDRESS_LINE_2 AS \"Billing Address Line 2\", uc.BILLING_ADDRESS_CITY AS \"Billing Address City\", uc.BILLING_ADDRESS_STATE AS \"Billing Address State\", \'IN\' AS \"Billing Address Country\", uc.BILLING_ADDRESS_PINCODE AS \"Billing Address Pincode\", NULL AS \"Billing Address Latitude\", NULL AS \"Billing Address Longitude\", uc.BILLING_ADDRESS_PHONE AS \"Billing Address Phone\", NULL AS \"Combination Identifier\", NULL AS \"Combination Description\", CONCAT(sdj.so_code_so_number, sdj.item_seq) AS \"Sale Order Item Code*\", \'STD\' AS \"Shipping Method*\", sdj.SKU AS \"Item SKU Code*\", NULL AS \"Channel Product Id\", NULL AS \"Item Name\", NULL AS \"Requires Customization\", NULL AS \"Gift Wrap\", uc.ACC_CODE AS \"Gift Message*\", sdj.cost_price AS \"Selling Price\", 0 AS \"Discount\", 0 AS \"Shipping Charges\", NULL AS \"Shipping Method Charges\", NULL AS \"COD Service Charges\", NULL AS \"Gift Wrap Charges\", NULL AS \"Voucher Code\", NULL AS \"Voucher Value\", NULL AS \"Store Credit\", NULL AS \"Packet Number\", NULL AS \"On Hold\", NULL AS \"Order Date as dd/mm/yyyy hh:MM:ss\", NULL AS \"Channel Order Processing Date as dd/MM/yyyy hh:mm:ss\", NULL AS \"Shipping Provider\", NULL AS \"Tracking Number\", sdj.ALLOCATED_UNITS AS \"Quantity\", NULL AS \"Quantity In Combo\", NULL AS \"Prepaid Amount\", NULL AS \"Customer Code\", NULL AS \"Currency Code\", NULL AS \"Customer GSTIN\", NULL AS \"Order Total Shipping Charges\", TO_CHAR(DATEADD(\'hour\', 16, DATEADD(\'day\', 2, CURRENT_DATE()::timestamp_ntz)),\'DD-MM-YYYY HH:MI AM\') AS \"Fulfillment Tat\", NULL AS \"Shipping Package Type Code\", NULL AS \"Transaction Id\", NULL AS \"Transaction Date as dd/MM/yyyy hh:mm:ss\", NULL AS \"Amount Paid\", NULL AS \"Payment Mode\", NULL AS \"Transaction Note\", sdj.facility AS \"Facility Code\", sdj.so_code_so_number AS \"Parent Sale Order Code\", NULL AS \"Item Tag\", NULL AS \"CHANNEL_ORDER_NUMBER\", uc.BILLING_ADDRESS_COUNTRY AS \"DiscountCode\", uc.ACC_CODE AS \"GiftMessage\", \'QCOM\' AS \"Order_Type\", CASE WHEN sdj.facility = \'SAPL-NORTH-TAURU\' AND uc.SHIPPING_ADDRESS_STATE = \'Haryana\' then \'ST\' WHEN sdj.facility IN (\'SAPL-WH1\', \'SAPL-WH2\') AND uc.SHIPPING_ADDRESS_STATE = \'Karnataka\' THEN \'ST\' ELSE \'WS\' END AS \"SaleInvoicePrefix\", NULL AS \"SnitchOnline\", uc.STORE_CODE AS \"STORE-CODE*\" FROM store_details_join_seq sdj LEFT JOIN STORE_DETAILS_UC uc ON sdj.branch_code = uc.store_code ), SO_FILTER AS ( SELECT \"Sales Order Code*\", SUM(\"Quantity\") AS total_qty FROM FINAL_OUTPUT GROUP BY 1 HAVING SUM(\"Quantity\") >= 15 ) SELECT * FROM FINAL_OUTPUT WHERE \"Sales Order Code*\" IN (SELECT \"Sales Order Code*\" FROM SO_FILTER) ORDER BY \"STORE-CODE*\", \"Facility Code\" ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            